+// RF-005, ADR-002: anular devuelve una factura nueva "anulada" con el motivo; la original no cambia.
+export function anularFactura(factura, motivo) {
+  if (typeof motivo !== "string" || motivo.trim() === "") throw new Error("La anulación necesita un motivo");
+  if (factura?.estado !== "emitida") throw new Error("Solo se puede anular una factura emitida");
+  return Object.freeze({ ...factura, estado: "anulada", motivo: motivo.trim() });
+}
